import React, { useContext, useEffect, useState } from 'react';
import {
    Alert, Box, Card, CardContent, Container, Grid, List, ListItem, Typography, Button, Dialog, DialogContent, Fab, DialogContentText, DialogActions,
    Modal
} from '@mui/material';
import { MainContext } from '../Contexts/MainContext';
import caracData from '../carac.json';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import OpenInFullIcon from '@mui/icons-material/OpenInFull';
import codexspe from '../codexspe.json';
import InfoIcon from '@mui/icons-material/Info';

export default function GamePage() {
    const codexspeJSON = codexspe;
    const [refs, setRefs] = useState([]);
    const [open, setOpen] = useState(false);
    const [infos, setInfos] = useState([]);
    const [formattedInfos, setFormattedInfos] = useState(null);
    const caracJSON = caracData;
    const [speciales, setSpeciales] = useState([]);
    const [openSpe, setOpenSpe] = useState(false);

    const {
        selectedCodexLogo,
        selectedCarteIndex,
        cartes,
        calculateCarteValue,
        selectedCodex,
        calculateTotalValue,
        maxCarte,
        selectedFaction,  // Ajout de selectedFaction ici
        alertRare,
        totalRareValue,
        isGamePageVisible,
        selectedStrategie,
        selectedInitiative,
    } = useContext(MainContext);

    const handleClickOpen = () => {
        setOpen(true);
    };

    const handleClose = () => {
        setOpen(false);
    };

    // Fonction pour agréger les références des options et les stocker dans l'état
    function extractAndConcatRefs(data) {
        return data.reduce((acc, item) => {
            if (Array.isArray(item.ref)) {
                acc = acc.concat(item.ref);  // Concatène les tableaux
            } else if (typeof item.ref === 'string') {
                acc.push(item.ref);  // Ajoute les strings directement
            }
            return acc;
        }, []);
    }

    // Fonction à déclencher lors du clic
    const handleConcatRefsClick = (options) => {
        const concatenatedRefs = extractAndConcatRefs(options);
        setRefs(concatenatedRefs);
        updateInfos(concatenatedRefs);
        handleClickOpen();
    };

    // Fonction pour récupérer les caractéristiques correspondant à chaque référence dans le tableau concatenatedRefs
    function getInfoByOption(refs) {
        if (refs && refs.length > 0 && caracJSON && selectedFaction) {
            const infos = [];
            const filteredCaracJSON = caracJSON.filter(item => item.faction === selectedFaction);

            refs.forEach(ref => {
                filteredCaracJSON.forEach(item => {
                    const matchingStats = item.stat.filter(stat => stat.Nom === ref);
                    matchingStats.forEach(stat => {
                        const info = {
                            Nom: stat.Nom,
                            Type: stat.Type,
                            Rang: stat.rang,
                            Vitesse: stat.Vitesse,
                            Blindage: stat.Blindage,
                            CC: stat.CC,
                            FF: stat.FF,
                            Notes: stat.Notes,
                            armes: stat.armes.map(arme => `${arme.Arme} - ${arme.Portée} - ${arme['Puissance de feu']}`)
                        };
                        infos.push(info);
                    });
                });
            });
            return infos;
        } else {
            return [];
        }
    }

    //Pour récupérer les régles spéciales du codex
    function getSpeByCodex() {
        if (codexspeJSON && selectedCodex) {
            const infos = [];

            // Filtrer les éléments du JSON en fonction du codex sélectionné
            const filteredCodexspeJSON = codexspeJSON.filter(item => item.codex === selectedCodex);

            // Extraire les règles spéciales et organiser les données
            filteredCodexspeJSON.forEach(item => {
                if (item.speciales && item.speciales.length > 0) {
                    item.speciales.forEach(speciale => {
                        Object.entries(speciale).forEach(([title, content]) => {
                            infos.push({ title, content }); // Stocker chaque règle avec son titre et contenu
                        });
                    });
                }
            });

            return infos; // Retourner un tableau structuré avec titre et contenu séparés
        } else {
            return []; // Retourner un tableau vide si aucune donnée n'est trouvée
        }
    }

    // Gérer l'ouverture/fermeture de la modal
    const handleOpenSpe = () => {
        const data = getSpeByCodex(); // Appeler la fonction pour récupérer les règles
        setSpeciales(data); // Mettre à jour l'état avec les règles récupérées
        setOpenSpe(true);
    };

    const handleCloseSpe = () => setOpenSpe(false);


    // Fonction pour mettre en forme les caractéristiques des options sélectionnées
    function formattedContent(infos) {
        return (
            <Box width={'100%'}>
                {infos.map((row, index) => (
                    <Grid container item key={index} alignItems={'center'} marginBottom={1}>
                        <Grid item xs={8.5} style={{ borderTop: 1, backgroundColor: '#838383' }}>
                            <Typography variant='body2' color={'white'}><b>{row.Nom}</b></Typography>
                        </Grid>
                        <Grid item xs={1} style={{ borderTop: 1, backgroundColor: '#838383' }}>
                            <Typography variant='body2' color={'white'}><b>{row.Type}</b></Typography>
                        </Grid>
                        <Grid item xs={2.5}
                            container
                            justifyContent="center"  // Centre horizontalement
                            alignItems="center"      // Centre verticalement
                            style={{ borderTop: 1, backgroundColor: '#838383' }}>
                            <img
                                src={process.env.PUBLIC_URL + '/' + row.Type + '.png'}
                                alt="Logo"
                                style={{
                                    height: '20px',
                                    objectFit: 'contain' // Garde les proportions de l'image
                                }}
                            /></Grid>
                        <Grid item xs={4}><Typography fontSize={12}><b>Vitesse :</b> {row.Vitesse}</Typography></Grid>
                        <Grid item xs={4}><Typography fontSize={12}><b>Blindage : </b>{row.Blindage}</Typography></Grid>
                        <Grid item xs={2}><Typography fontSize={12}><b>CC : </b>{row.CC}</Typography></Grid>
                        <Grid item xs={2}><Typography fontSize={12}><b>FF : </b>{row.FF}</Typography></Grid>
                        <Grid item xs={12}><Typography fontSize={12}><b>Armes / Portée / Puissance</b></Typography></Grid>

                        <Grid item xs={12}>
                            <Grid container alignContent={'center'}>
                                {row.armes.map((arme, idx) => (
                                    <Grid item xs={12} key={idx}>
                                        <Typography key={idx} fontSize={10} sx={{ fontSize: '8pt' }}>
                                            {arme}
                                        </Typography>
                                    </Grid>
                                ))}
                            </Grid>
                        </Grid>
                        <Grid item xs={12}
                            style={{ borderTop: 1, backgroundColor: '#e9e9e9' }}>
                            <Typography fontSize={10} sx={{ lineHeight: 1.1, margin: 1, padding: 0.5 }}    >
                                {row.Notes}
                            </Typography>
                        </Grid>
                    </Grid>
                ))}
            </Box>
        );
    }

    // Fonction pour mettre à jour les informations en fonction des références concaténées
    const updateInfos = (refs) => {
        const rawInfos = getInfoByOption(refs);
        setInfos(rawInfos);
        const content = formattedContent(rawInfos);
        setFormattedInfos(content);
    };

    return (
        <Container sx={{
            display: isGamePageVisible ? 'block' : 'none',
            height: '100%', backgroundColor: 'white', marginTop: 16,
            padding: 0
        }}
            maxWidth="100vw">
            <Grid container marginTop={2} direction="row">
                <Grid item xs={12} sx={{ padding: 0 }}>
                    <Box >
                        <Card display="flex" sx={{ justifyContent: "center", alignContent: 'center', alignItems: 'center' }}>
                            <CardContent sx={{ padding: 0.5 }}>
                                <Grid container>
                                    <Grid item xs={8} >
                                        <Typography variant="h4" fontSize={24}><b>Liste {selectedCodex}</b> {calculateTotalValue()} pts</Typography>
                                    </Grid>
                                    <Grid item xs={4}><img src={process.env.PUBLIC_URL + '/' + selectedCodexLogo} /></Grid>

                                    <Grid item xs={3}><Typography variant='body2'>Strategie : <b>{selectedStrategie}</b></Typography></Grid>
                                    <Grid item xs={3}><Typography variant='body2'>Formations : <b>{cartes.length}</b></Typography></Grid>
                                    <Grid item xs={12}><Typography variant='body2'>BLM : <b>{maxCarte.formation} {calculateCarteValue(maxCarte)} pts</b></Typography></Grid>

                                    <Grid item xs={12}><Typography variant='body2'>Initiative : {selectedInitiative}</Typography></Grid>

                                </Grid>
                            </CardContent>
                        </Card>
                    </Box>
                    {alertRare && <Alert severity='warning'>La valeur des formations rares ({totalRareValue}) dépasse les limites du codex</Alert>}
                </Grid>
            </Grid>

            <Grid container spacing={1} >
                {cartes.map((carte, carteIndex) => (
                    <Grid item xs={6} key={carteIndex}>
                        <Box >
                            <CardContent sx={{ padding: 0.1, paddingBottom: 0 }} className={`card ${selectedCarteIndex === carteIndex ? 'selected' : ''}`}>
                                <Grid container style={{
                                    borderTop: 1, backgroundColor: '#ededed',
                                    borderRadius: '8px'
                                }}>
                                    <Grid item xs={10} sx={{ padding: 0.5 }} >
                                        <Typography variant='h6' fontSize={16} onClick={() => handleConcatRefsClick(carte.options)}>
                                            <b>{carte.formation}</b> : {calculateCarteValue(carte)} pts
                                        </Typography>
                                    </Grid>
                                    <Grid item xs={2} sx={{ padding: 0.5 }} >
                                        <OpenInFullIcon fontSize='small' onClick={() => handleConcatRefsClick(carte.options)}></OpenInFullIcon>
                                    </Grid>
                                </Grid>
                                <List>
                                    {carte.options.map((option, optionIndex) => (
                                        <ListItem key={optionIndex} sx={{ padding: 0.5 }}>
                                            <Typography variant='body2' fontSize={12}>
                                                {option.selectedValue > 1 && `${option.selectedValue} `}
                                                {option.name} - : {option.value * option.selectedValue}
                                            </Typography>
                                        </ListItem>
                                    ))}
                                </List>
                            </CardContent>
                        </Box>
                    </Grid>
                ))}
            </Grid>

            {/* Modal pour afficher les infos formatées */}
            <Dialog open={open} onClose={handleClose} sx={{ '& .MuiDialog-paper': { width: '95%', height: '80%', maxWidth: '95%' } }}>
                <DialogContent sx={{ padding: 1 }}>
                    <DialogContentText>
                        <Typography variant="body1">
                            {formattedInfos}
                        </Typography>
                    </DialogContentText>
                </DialogContent>
                <DialogActions>
                    <Button onClick={handleClose} autoFocus>Fermer</Button>
                </DialogActions>
            </Dialog>

            <Fab
                color="primary"
                aria-label="add"
                onClick={handleOpenSpe}
                sx={{
                    position: "fixed",
                    bottom: 16,
                    right: 16,
                }}
            >
                <InfoIcon />
            </Fab>

            {/* Modal */}
            <Modal open={openSpe} onClose={handleCloseSpe}>
                <Box
                    sx={{
                        position: "absolute",
                        top: "50%",
                        left: "50%",
                        transform: "translate(-50%, -50%)",
                        width: "80%",
                        bgcolor: "background.paper",
                        boxShadow: 24,
                        p: 4,
                        borderRadius: 2,
                        maxHeight: "80vh",
                        overflowY: "auto",
                    }}
                >
                    <Typography variant="h6" component="h2" mb={2}>
                        Règles Spéciales
                    </Typography>
                    {speciales.map((rule, index) => (
                        <Box key={index} mb={3}>
                            <Typography variant="subtitle1" sx={{ fontWeight: "bold" }}>
                                {rule.title}
                            </Typography>
                            <div dangerouslySetInnerHTML={{ __html: rule.content }} />
                        </Box>
                    ))}
                </Box>
            </Modal>


        </Container>
    );
}
