import React, { useContext, useState, useEffect } from 'react';
import AddIcon from '@mui/icons-material/Add';
import OpenInFullIcon from '@mui/icons-material/OpenInFull';
import CloseFullscreenIcon from '@mui/icons-material/CloseFullscreen';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import CleaningServicesIcon from '@mui/icons-material/CleaningServices';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import HighlightOffIcon from '@mui/icons-material/HighlightOff';
import {
    Accordion, AccordionDetails, AccordionSummary, Alert, Box, Button,
    Card, CardContent, Container, Dialog, DialogActions,
    DialogContent, DialogContentText, DialogTitle, Divider, FormControl,
    Grid, IconButton, List, ListItem, ListItemText, MenuItem,
    Select, Stack, Typography, SpeedDial,
    Badge, keyframes, Modal, Popover
} from '@mui/material';
import { MainContext } from '../Contexts/MainContext';
import VisibilityIcon from '@mui/icons-material/Visibility';
import { styled } from '@mui/material/styles';
import InfoIcon from '@mui/icons-material/Info';
import Tooltip, { tooltipClasses } from '@mui/material/Tooltip';
import StarsIcon from '@mui/icons-material/Stars';
import SwipeableDrawer from '@mui/material/SwipeableDrawer';
import FormatListBulletedIcon from '@mui/icons-material/FormatListBulleted';
import AddCircleIcon from '@mui/icons-material/AddCircle';
import PlaylistAddIcon from '@mui/icons-material/PlaylistAdd';
import { useTranslation } from 'react-i18next';


// Définissez les keyframes pour une animation de "pop"
const popAnimation = keyframes`
  0% { transform: scale(1); }
  50% { transform: scale(1.5); } // Taille augmentée au milieu de l'animation
  100% { transform: scale(1); } // Retour à la taille normale
`;


export default function MainPage() {
    const {
        cartesSansNbacti,
        alertRare,
        handleToggleAllAccordions,
        formattedInfos,
        updateInfos,
        handleSelectCodex,
        handleOptionRemove,
        handleRemoveCarte,
        handleRemoveAllCartes,
        handleShowFormationOptions,
        handleCarteSelect,
        handleOptionSelect,
        handleFormationAndCreateCarte,
        handleShowOptions,
        formations,
        selectedFormationOptions,
        selectedCarteIndex,
        showCodexSelection,
        CodexSelectionPopup,
        handleCloseCodexSelection,
        selectedCodex,
        cartes,
        calculateCarteValue,
        open,
        handleClose,
        handleClickOpen,
        accordionStates,
        handleToggleAccordion,
        totalRareValue,
        scrollToSection,
        isGamePageVisible,
        totalValue,
        modalOpen,
        setModalOpen,
        modalMainOption,
        handleMainOptionChange,
        remainingOptions,
        modalOptions,
        tempSelections,
        handleSelectionChange,
        validateModalSelections,
        openModal,
        selectedShowOptions,
        isVersionPageVisible,
        isRulePageVisible
    } = useContext(MainContext)

    // Pour la Popover Note
    const [anchorNote, setAnchorNote] = useState(null);
    const [selectedNote, setSelectedNote] = useState("");
    const handleOpenNote = (event, note) => {
        setAnchorNote(event.currentTarget);
        setSelectedNote(note); // Met à jour la note correspondante
    };
    const handleCloseNote = () => {
        setAnchorNote(null);
        setSelectedNote("");
    };
    const openNote = Boolean(anchorNote);
    const { i18n, t } = useTranslation();

    // Pour la Popover Info
    const [anchorInfo, setAnchorInfo] = useState(null);
    const handleOpenInfo = (event) => {
        setAnchorInfo(event.currentTarget);
    };
    const handleCloseInfo = () => {
        setAnchorInfo(null);
    };
    const openInfo = Boolean(anchorInfo);
    ///////////////////////////

    // Pour la Popover Showoptions
    const [anchorShow, setAnchorShow] = useState(null);
    const handleOpenShow = (event, formation) => {
        setAnchorShow(event.currentTarget);
        handleShowOptions(formation); // Fonction pour afficher les options
    };
    const handleCloseShow = () => {
        setAnchorShow(null);
    };
    const openShow = Boolean(anchorShow);
    ///////////////////////////

    const [drawerOpen, setDrawerOpen] = useState(false);

    const toggleDrawer = (open) => (event) => {
        if (event.type === 'keydown' && (event.key === 'Tab' || event.key === 'Shift')) {
            return;
        }
        setDrawerOpen(open);
    };

    const [isClicked, setIsClicked] = useState(false);

    // Déclenche l'animation lors d'un changement de totalValue
    useEffect(() => {
        setIsClicked(true); // Déclenche l'animation
        const timer = setTimeout(() => setIsClicked(false), 1000); // Réinitialise après 1000 ms
        return () => clearTimeout(timer); // Nettoie le timer
    }, [cartes]); // Dépendance à totalValue

    const shouldDisplay = !isGamePageVisible && !isVersionPageVisible && !isRulePageVisible;


    return (
        <Container maxWidth="100vw" sx={{
            displayPrint: 'none',
            display: shouldDisplay ? 'block' : 'none',
            minHeight: '100vh', marginTop: 10,
            paddingLeft: 0, paddingRight: 0,
        }} >
            {showCodexSelection && (
                <CodexSelectionPopup onClose={handleCloseCodexSelection} onSelectCodex={handleSelectCodex} />
            )}
            {selectedCodex && (
                <Stack spacing={2} >
                    {/* Colonne formation */}
                    <Box xs={12} md={4} >
                        <Card sx={{ marginTop: 5 }}>
                            <CardContent >
                                <Typography sx={{ fontSize: '18pt', fontStyle: 'bold', textTransform: 'uppercase', }} >{t('formation')}</Typography>
                                <List component="div">
                                    {selectedCodex &&
                                        formations.map((group, groupIndex) => (
                                            <div key={groupIndex}>
                                                <ListItemText>
                                                    <Typography sx={{ fontSize: '14pt', lineHeight: 1 }}>{group.groupName} </Typography>
                                                    <Typography variant='caption'
                                                        sx={{ fontSize: '8pt', lineHeight: 1 }}
                                                    >{group.detail}</Typography>
                                                </ListItemText>
                                                <List >
                                                    {group.formations.map((formation, formationIndex) => (
                                                        <ListItem sx={{ margin: 0, padding: 0 }} key={formationIndex} >
                                                            <Grid container alignContent={'right'} alignItems={'center'}>
                                                                <Grid item xs={1}>
                                                                    <IconButton color="default"
                                                                        sx={{ margin: 0.2, padding: 0, paddingRight: 1, }}
                                                                        onClick={(event) => {
                                                                            handleOpenShow(event, formation); // Fonction supplémentaire à déclencher
                                                                        }}
                                                                    >
                                                                        <InfoIcon sx={{ fontSize: 20 }} ></InfoIcon>
                                                                    </IconButton>
                                                                </Grid>
                                                                <Grid item xs={10}>
                                                                    <Typography variant='list'>{formation.name}</Typography>
                                                                </Grid>
                                                                <Grid item xs={1}>
                                                                    <IconButton size="small"
                                                                        sx={{ margin: 0, padding: 0, paddingLeft: 1 }}
                                                                        onClick={() => {
                                                                            handleFormationAndCreateCarte(formation);
                                                                            scrollToSection();
                                                                        }}>
                                                                        <PlaylistAddIcon color='#818181'></PlaylistAddIcon>
                                                                    </IconButton>
                                                                </Grid>
                                                            </Grid>
                                                        </ListItem>
                                                    ))}
                                                </List>
                                            </div>
                                        ))}
                                </List>
                            </CardContent>
                        </Card>
                    </Box>
                    {/* Colonne option */}
                    <Box xs={12} id="options">
                        <Card >
                            <CardContent>
                                <Typography sx={{ fontSize: '18pt', fontStyle: 'bold', textTransform: 'uppercase', }}>{t('option')}</Typography>
                                <Stack>
                                    {selectedFormationOptions &&
                                        selectedFormationOptions.map((option, optionIndex) => (
                                            <>{!option.refoption && (
                                                <List sx={{ margin: 0, padding: 0 }}>
                                                    <ListItem sx={{ margin: 0, padding: 0 }} key={"formation-option" + optionIndex} data-title={option.note}>
                                                        <Grid container alignContent={'center'} alignItems={'center'}>
                                                            <Grid item xs={1}>
                                                                {option.ref && (
                                                                    <InfoIcon sx={{ fontSize: 20, cursor: 'pointer', }}
                                                                        color="secondary"
                                                                        onClick={(event) => {
                                                                            handleOpenInfo(event); // Passe l'événement pour positionner le Popover
                                                                            updateInfos(option);  // Met à jour les informations à afficher                                                                            
                                                                        }}
                                                                    ></InfoIcon>
                                                                )}
                                                                <Popover
                                                                    open={openInfo}
                                                                    anchorEl={anchorInfo}
                                                                    onClose={handleCloseInfo}
                                                                    anchorOrigin={{
                                                                        vertical: 'bottom',
                                                                        horizontal: 'left',
                                                                    }}
                                                                    transformOrigin={{
                                                                        vertical: 'top',
                                                                        horizontal: 'left',
                                                                    }}
                                                                >
                                                                    <Typography sx={{ padding: 2 }}>{formattedInfos}</Typography>
                                                                </Popover>
                                                            </Grid>
                                                            <Grid item xs={10}>
                                                                <Typography variant='list'
                                                                    onClick={(event) => {
                                                                        if (option.note) {
                                                                            handleOpenNote(event, option.note); // Passe l'événement pour positionner le Popover
                                                                        }
                                                                    }}
                                                                    style={{
                                                                        backgroundColor: option.principale
                                                                            ? '#e5eef5'
                                                                            : option.refoption
                                                                                ? '#fff4eb'
                                                                                : 'white',
                                                                        fontSize: option.refoption === true ? '12px' : '16px',
                                                                        marging: option.refoption === true ? '0px' : '5px',
                                                                        marginLeft: option.refoption === true ? '10px' : '0px',
                                                                    }}
                                                                >{option.name} : {option.value} {t('pts')}
                                                                </Typography>
                                                                <Popover
                                                                    open={openNote}
                                                                    anchorEl={anchorNote}
                                                                    onClose={handleCloseNote}
                                                                    anchorOrigin={{
                                                                        vertical: 'bottom',
                                                                        horizontal: 'left',
                                                                    }}
                                                                    transformOrigin={{
                                                                        vertical: 'top',
                                                                        horizontal: 'left',
                                                                    }}
                                                                >
                                                                    <Typography sx={{ padding: 2, fontSize: 12 }}>{selectedNote}</Typography>
                                                                </Popover>
                                                            </Grid>
                                                            {option.max && (
                                                                <Grid item xs={1}>
                                                                    {option.nbrefoptions ? ( // Si `nbrefoptions` existe
                                                                        <IconButton
                                                                            onClick={() => {
                                                                                const relatedOptions = selectedFormationOptions.filter(opt => opt.refoption);
                                                                                if (option.nbrefoptions) {
                                                                                    openModal(option, relatedOptions);
                                                                                } else {
                                                                                    // Appeler directement `handleOptionSelect` si pas de `nbrefoptions`
                                                                                    handleOptionSelect(option, selectedCarteIndex, 1);
                                                                                }
                                                                            }}
                                                                        >
                                                                            <AddCircleIcon />
                                                                        </IconButton>
                                                                    ) : ( // Sinon, afficher un selecteur pour les options sans `nbrefoptions`
                                                                        <FormControl >
                                                                            <Select variant="standard" size='1' value={0}
                                                                                onChange={(e) => handleOptionSelect(option, selectedCarteIndex, parseInt(e.target.value))}
                                                                            >
                                                                                {option.min !== 0 && <option value={0}>0</option>}
                                                                                {[...Array(option.max - option.min + 1)].map((_, i) => (
                                                                                    <MenuItem key={"formation-option-item" + i + option.min} value={i + option.min}>
                                                                                        {i + option.min}
                                                                                    </MenuItem>
                                                                                ))}
                                                                            </Select>
                                                                        </FormControl>)}
                                                                </Grid>
                                                            )}
                                                            {!option.max && (
                                                                <Grid item xs={1} md={1} display="flex" justifyContent="flex-end">
                                                                    <IconButton
                                                                        onClick={() => {
                                                                            if (option.nbrefoptions) {
                                                                                const relatedOptions = selectedFormationOptions.filter(opt => opt.refoption);
                                                                                openModal(option, relatedOptions);
                                                                            }
                                                                            else {
                                                                                // Appeler directement `handleOptionSelect` si pas de `nbrefoptions`
                                                                                handleOptionSelect(option, selectedCarteIndex, 1);
                                                                            }
                                                                        }}
                                                                    >
                                                                        <AddCircleIcon />
                                                                    </IconButton>
                                                                </Grid>
                                                            )}

                                                        </Grid>
                                                    </ListItem>
                                                    <Divider variant='fullWidth' />
                                                </List>
                                            )}  </>
                                        ))}
                                </Stack>
                            </CardContent>
                        </Card>
                    </Box>
                    <Box style={{ position: 'fixed', bottom: 10, right: 10 }}>
                        <SpeedDial
                            sx={{
                                '& .MuiSpeedDialFab-root': {
                                    backgroundColor: '${theme.palette.secondary.main} !important'
                                }
                            }}
                            onClick={toggleDrawer(true)}
                            ariaLabel="Liste"
                            icon={<FormatListBulletedIcon />}
                        >
                            <Badge
                                badgeContent={cartesSansNbacti.length}
                                color='secondary'
                                overlap='rectangular'
                                sx={{
                                    position: 'absolute', // Position absolue pour chevaucher
                                    top: 18,
                                    right: 10,
                                    zIndex: 1000,
                                    animation: isClicked ? `${popAnimation} 0.5s ease-in-out` : 'none', // Applique l'animation conditionnellement
                                }}
                            />
                        </SpeedDial>
                    </Box>
                </Stack>
            )}
            {/* Cartes */}
            <SwipeableDrawer
                anchor="bottom"
                open={drawerOpen}
                onClose={toggleDrawer(false)}
                onOpen={toggleDrawer(true)}
            >
                <Box sx={{ width: '90vw', padding: 2 }} >
                    <Grid container justifyContent={'left'} spacing={2}>
                        <Grid item xs={3} md={3}>
                            <Typography variant="h5">{t('list')}</Typography>
                        </Grid>
                        <Grid item xs={7} md={7}>
                            < Tooltip title={t('open_all')}>
                                <IconButton onClick={() => handleToggleAllAccordions(true)}>
                                    <OpenInFullIcon ></OpenInFullIcon>
                                </IconButton>
                            </Tooltip>
                            < Tooltip title={t('close_all')}>
                                <IconButton onClick={() => handleToggleAllAccordions(false)}>
                                    <CloseFullscreenIcon ></CloseFullscreenIcon>
                                </IconButton>
                            </Tooltip>
                        </Grid>
                        <Grid item xs={2} md={2}>
                            {cartes.length > 0 && (
                                <Box display="flex" justifyContent="flex-end">
                                    <Tooltip title={t('tooltip.clear_list')}>
                                        <IconButton className="remove-all-button" onClick={handleClickOpen} sx={{ displayPrint: 'none' }}>
                                            <CleaningServicesIcon />
                                        </IconButton>
                                        <Dialog open={open} onClose={handleClose}>
                                            <DialogTitle id="alert-dialog-title">
                                                {t('dialog.clear_list_title')}
                                            </DialogTitle>
                                            <DialogContent>
                                                <DialogContentText id="alert-dialog-description">
                                                    {t('dialog.clear_list_confirmation')}
                                                </DialogContentText>
                                            </DialogContent>
                                            <DialogActions>
                                                <Button onClick={handleClose}>{t('dialog.reject')}</Button>
                                                <Button onClick={handleRemoveAllCartes} autoFocus>{t('dialog.accept')}</Button>
                                            </DialogActions>
                                        </Dialog>
                                    </Tooltip>
                                </Box>
                            )}
                        </Grid>
                        {alertRare && (
                            <Alert severity="warning" variant="outlined">
                                {t('alert.rare_value_exceeded', { value: totalRareValue })}
                            </Alert>
                        )}
                    </Grid>

                    <Stack spacing={1}>
                        {cartes.map((carte, carteIndex) => (
                            <Accordion disableGutters
                                onChange={() => handleToggleAccordion(carteIndex)}
                                expanded={accordionStates[carteIndex]}
                                defaultExpanded="true"
                                onClick={() => {
                                    handleCarteSelect(carteIndex);
                                    handleShowFormationOptions(carte.optionbase);
                                }}
                                sx={{
                                    border: selectedCarteIndex === carteIndex ? '2px solid #427bb9' : '0px #ccc',
                                    background: selectedCarteIndex === carteIndex ? ' #dcdcdc' : ' #ffffff'
                                }}
                                key={carteIndex}
                                className={`card ${selectedCarteIndex === carteIndex ? 'selected' : ''}`}
                            >
                                <AccordionSummary
                                    expandIcon={<ExpandMoreIcon />}
                                    onChange={() => handleToggleAccordion(carteIndex)}
                                    sx={{ padding: 0, height: '25px' }}

                                >
                                    <Grid container direction="row" justifyContent="center" alignItems="center">
                                        <Grid item xs={1.5} md={1.5} sx={{ display: 'flex', justifyContent: 'flex-start' }}>
                                            <Tooltip title="Supprimer la formation">
                                                <IconButton size="small" color='warning' onClick={() => handleRemoveCarte(carteIndex)}>
                                                    <HighlightOffIcon />
                                                </IconButton>
                                            </Tooltip>
                                        </Grid>
                                        <Grid item xs={10.5} md={10.5} display="flex"
                                            alignItems="center"
                                            alignContent="flex-start"
                                            padding={0}
                                        >
                                            <Typography
                                                sx={{ fontSize: '12pt', fontStyle: 'bold', textTransform: 'uppercase', }}
                                                component="span">
                                                {carte.GrpPrincipal && (
                                                    <Tooltip title={t('tooltip.main_formation')}>
                                                        <StarsIcon sx={{ fontSize: 15 }} />
                                                    </Tooltip>
                                                )} &nbsp;
                                                {carte.formation}


                                                {accordionStates[carteIndex] === false && (
                                                    <span sx={{ fontSize: '10pt' }}>
                                                        {' '}
                                                        ({calculateCarteValue(carte)} {t('pts')})
                                                    </span>
                                                )}
                                            </Typography>
                                        </Grid>
                                    </Grid>
                                </AccordionSummary>
                                <AccordionDetails sx={{ padding: 1, paddingTop: 0 }}>
                                    <List>
                                        {carte.options.map((option, optionIndex) => (
                                            <ListItem key={optionIndex} sx={{ margin: 0, padding: 0, paddingLeft: option.refoption ? 2 : 0 }}>
                                                <Typography style={{
                                                    fontWeight: option.principale === true ? 'bold'
                                                        : option.tagrefoptions ? 'bold'
                                                            : 'normal',
                                                    fontStyle: option.refoption ? 'italic' : 'normal',
                                                    fontSize: 14
                                                }}>
                                                    {((option.refoption || option.selectedValue > 1) && `${option.selectedValue} `)}
                                                    {option.name}
                                                    {option.valueSingle ? ` - ${option.value}` : (option.value > 0 && ` - ${option.value * option.selectedValue}`)}

                                                </Typography>
                                                <Tooltip title="Supprimer l'option">
                                                    <IconButton onClick={() => handleOptionRemove(option, carteIndex)} sx={{ displayPrint: 'none' }}>
                                                        <HighlightOffIcon color="warning" sx={{ fontSize: 15 }} />
                                                    </IconButton>
                                                </Tooltip>
                                            </ListItem>
                                        ))}
                                    </List>
                                    <Typography variant="body1">{t('total')} : {calculateCarteValue(carte)}</Typography>
                                </AccordionDetails>
                            </Accordion>
                        ))}
                    </Stack>
                </Box>
            </SwipeableDrawer>

            {/* Modale */}
            {modalOpen && (
                <Modal open={modalOpen} onClose={() => setModalOpen(false)}>
                    <Box
                        sx={{
                            backgroundColor: 'white',
                            width: '85%',
                            maxHeight: '80vh',
                            position: 'absolute',
                            top: '50%',
                            left: '50%',
                            transform: 'translate(-50%, -50%)',
                            padding: 3,
                            borderRadius: 2,
                            boxShadow: 3,
                            overflowY: 'auto',
                        }}
                    >
                        <Box mb={2}>
                            {/* Titre */}
                            <Typography variant="h6">{modalMainOption.name}  {modalMainOption.value > 0 ? `: ${modalMainOption.value} t('pts')` : ''}</Typography>

                            {/* Sélecteur principal */}
                            {modalMainOption.min !== undefined && modalMainOption.max !== undefined ? (
                                <Select
                                    value={modalMainOption.nbrefoptions} // Valeur synchronisée
                                    onChange={(e) => handleMainOptionChange(parseInt(e.target.value, 10))} // Gestion des modifications
                                    fullWidth
                                >
                                    {[...Array((modalMainOption.max || 1) - (modalMainOption.min || 0) + 1)].map((_, i) => (
                                        <MenuItem key={i} value={i + (modalMainOption.min || 0)}>
                                            {i + (modalMainOption.min || 0)}
                                        </MenuItem>
                                    ))}
                                </Select>
                            ) : (
                                remainingOptions > 0 && ( // Condition pour afficher le texte
                                    <Typography>
                                        {t('options.remaining', { count: remainingOptions })}
                                    </Typography>
                                )
                            )}

                            {/* Alertes conditionnelles */}
                            {remainingOptions === 0 && (
                                <Alert severity="success" style={{ marginTop: "8px" }}>
                                    {t('options.all_taken')}
                                </Alert>
                            )}
                            {remainingOptions < 0 && (
                                <Alert severity="error" style={{ marginTop: "8px" }}>
                                    {t('options.too_many')}
                                </Alert>
                            )}
                        </Box>


                        <Grid container spacing={2}>
                            {modalOptions.map((opt) => (
                                <Grid
                                    container
                                    item
                                    spacing={2}
                                    alignItems="center"
                                    key={opt.name}
                                >
                                    {/* Nom de l'option */}
                                    <Grid item xs={8}>
                                        <Typography variant="subtitle1">{opt.name} {opt.value > 0 ? `: ${opt.value} pts` : ''}</Typography>
                                    </Grid>
                                    {/* Sélecteur pour l'option */}
                                    <Grid item xs={4}>
                                        <Select
                                            value={tempSelections[opt.name] ?? opt.min} // Valeur par défaut ou actuelle
                                            onChange={(e) => handleSelectionChange(opt.name, parseInt(e.target.value))}
                                        >
                                            {[...Array(opt.max - opt.min + 1)].map((_, i) => (
                                                <MenuItem key={i} value={i + opt.min}>
                                                    {i + opt.min}
                                                </MenuItem>
                                            ))}
                                        </Select>
                                    </Grid>
                                </Grid>
                            ))}
                        </Grid>
                        <Grid container spacing={2} mt={3}>
                            <Grid item xs={6}>
                                <Button
                                    variant="outlined"
                                    color="secondary"
                                    fullWidth
                                    onClick={() => setModalOpen(false)}
                                >
                                    {t('cancel')}
                                </Button>
                            </Grid>
                            <Grid item xs={6}>
                                <Button
                                    variant="contained"
                                    color="secondary"
                                    fullWidth
                                    disabled={remainingOptions !== 0}
                                    onClick={validateModalSelections}
                                >

                                    {t('validate')}
                                </Button>
                            </Grid>
                        </Grid>
                    </Box>
                </Modal>
            )}

            {/* Pop showOption */}
            <Popover
                open={openShow}
                anchorEl={anchorShow}
                onClose={handleCloseShow}
                anchorOrigin={{
                    vertical: 'bottom',
                    horizontal: 'left',
                }}
                transformOrigin={{
                    vertical: 'top',
                    horizontal: 'left',
                }}
            >
                {selectedShowOptions.map((option, optionIndex) => (
                    <List sx={{ margin: 0, padding: 0 }}>
                        <ListItem sx={{ margin: 0, padding: 0 }} key={"formation-option" + optionIndex} data-title={option.note}>
                            <Grid container alignContent={'center'} alignItems={'center'}>
                                <Grid item xs={12} padding={0.5}>
                                    <Typography variant='list'
                                        style={{
                                            paddingLeft: option.refoption ? 5 : 1,
                                            backgroundColor: option.principale
                                                ? '#ebf6fe'
                                                : !option.refoption
                                                    ? '#f9fdff'
                                                    : 'white',
                                            borderRadius: 3,
                                            fontSize: option.refoption ? '10px' : '12px',
                                            fontStyle: option.refoption ? 'italic' : 'normal',
                                            fontWeight: !option.refoption ? 'bold' : 'normal',

                                        }}
                                    >{option.name} : {option.value} {t('pts')}
                                    </Typography>
                                </Grid>
                            </Grid>
                        </ListItem>
                    </List>
                ))}
            </Popover>
        </Container >

    );

}