import React, { useContext, useState } from 'react';
import AddIcon from '@mui/icons-material/Add';
import OpenInFullIcon from '@mui/icons-material/OpenInFull';
import CloseFullscreenIcon from '@mui/icons-material/CloseFullscreen';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import CleaningServicesIcon from '@mui/icons-material/CleaningServices';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import HighlightOffIcon from '@mui/icons-material/HighlightOff';
import {
    Accordion, AccordionDetails, AccordionSummary, Alert, Box, Button,
    Card, CardContent, Container, Dialog, DialogActions,
    DialogContent, DialogContentText, DialogTitle, Divider, FormControl,
    Grid, IconButton, List, ListItem, ListItemText, MenuItem,
    Select, Stack, Typography, TextField, Modal, Popover
} from '@mui/material';
import { MainContext } from '../Contexts/MainContext';
import VisibilityIcon from '@mui/icons-material/Visibility';
import { styled } from '@mui/material/styles';
import InfoIcon from '@mui/icons-material/Info';
import Tooltip, { tooltipClasses } from '@mui/material/Tooltip';
import StarsIcon from '@mui/icons-material/Stars';
import AddCircleIcon from '@mui/icons-material/AddCircle';
import PlaylistAddIcon from '@mui/icons-material/PlaylistAdd';
import { useTranslation } from 'react-i18next';

export default function MainPage() {

    //Style pour le tooltip
    const NoMaxWidthTooltip = styled(({ className, ...props }) => (
        <Tooltip {...props} classes={{ popper: className }} sx={{ fontSize: '14pt' }} />
    ))
        ({
            [`& .${tooltipClasses.tooltip}`]: {
                maxWidth: '70% !important',
            },
        });

    const {
        selectedShowOptions,
        alertRare,
        handleToggleAllAccordions,
        formattedInfos,
        updateInfos,
        handleSelectCodex,
        handleOptionRemove,
        handleRemoveCarte,
        handleRemoveAllCartes,
        handleShowFormationOptions,
        handleCarteSelect,
        handleOptionSelect,
        handleFormationAndCreateCarte,
        handleShowOptions,
        formations,
        selectedFormationOptions,
        selectedCarteIndex,
        showCodexSelection,
        CodexSelectionPopup,
        handleCloseCodexSelection,
        selectedCodex,
        cartes,
        calculateCarteValue,
        open,
        handleClose,
        handleClickOpen,
        accordionStates,
        handleToggleAccordion,
        totalRareValue, totalRareSpeValue,
        scrollToSection,
        isGamePageVisible,
        modalOpen,
        setModalOpen,
        modalMainOption,
        handleMainOptionChange,
        remainingOptions,
        modalOptions,
        tempSelections,
        handleSelectionChange,
        validateModalSelections,
        openModal,
        isVersionPageVisible,
        isRulePageVisible
    } = useContext(MainContext)

    ///////////////////////////////////////
    const { i18n, t } = useTranslation();
    // Pour la Popover Showoptions
    const [anchorShow, setAnchorShow] = useState(null);
    const handleOpenShow = (event, formation) => {
        setAnchorShow(event.currentTarget);
        handleShowOptions(formation); // Fonction pour afficher les options

    };
    const handleCloseShow = () => {
        setAnchorShow(null);
    };
    const openShow = Boolean(anchorShow);
    ///////////////////////////

    const shouldDisplay = !isGamePageVisible && !isVersionPageVisible && !isRulePageVisible;

    return (
        <Container maxWidth="100vw" sx={{
            displayPrint: 'none',
            display: shouldDisplay ? 'block' : 'none',
            minHeight: '85vh'
        }} >
            {showCodexSelection && (
                <CodexSelectionPopup onClose={handleCloseCodexSelection} onSelectCodex={handleSelectCodex} />
            )}
            {selectedCodex && (
                <Grid container spacing={1} marginTop={2} sx={{ minHeight: '100vh', marginTop: '70px' }} >
                    {/* Colonne formation */}
                    <Grid item xs={12} md={4}  >
                        <Card sx={{ borderRadius: 5 }}>
                            <CardContent >
                                <Typography variant="h4">{t('formation')}</Typography>
                                <List>
                                    {selectedCodex &&
                                        formations.map((group, groupIndex) => (
                                            <div key={groupIndex}>
                                                <ListItemText>
                                                    <Typography variant='h6'>{group.groupName} </Typography>
                                                    <Typography variant='caption'>{group.detail}</Typography>
                                                </ListItemText>
                                                <List >
                                                    {group.formations.map((formation, formationIndex) => (
                                                        <ListItem sx={{ margin: 0, padding: 0, borderBlockEnd: '1px solid rgba(0, 0, 0, 0.1)' }} key={formationIndex} >
                                                            <Grid container alignContent={'right'} alignItems={'center'}>
                                                                <Grid item xs={1.5}>
                                                                    <IconButton size="small" color="default"
                                                                        onClick={(event) => {
                                                                            handleOpenShow(event, formation); // Fonction supplémentaire à déclencher
                                                                        }}
                                                                    >
                                                                        <InfoIcon></InfoIcon>
                                                                    </IconButton>
                                                                </Grid>
                                                                <Grid item xs={9.5}>
                                                                    <Typography variant='body1'>{formation.name}</Typography>
                                                                </Grid>
                                                                <Grid item xs={1}>
                                                                    <IconButton color="secondary" onClick={() => {
                                                                        handleFormationAndCreateCarte(formation);
                                                                        scrollToSection();
                                                                    }}>
                                                                        <PlaylistAddIcon />
                                                                    </IconButton>
                                                                </Grid>
                                                            </Grid>
                                                        </ListItem>
                                                    ))}
                                                </List>
                                            </div>
                                        ))}
                                </List>
                            </CardContent>
                        </Card>
                    </Grid>
                    {/* Colonne option */}
                    <Grid item xs={12} md={4} id="options">
                        <Card sx={{ position: 'sticky', top: 70, zIndex: 1, borderRadius: 5 }}>
                            <CardContent>
                                <Typography variant="h4">{t('option')}</Typography>
                                <Stack>
                                    {selectedFormationOptions &&
                                        selectedFormationOptions.map((option, optionIndex) =>
                                            !option.refoption && (
                                                <List key={`formation-option-list-${optionIndex}`}>
                                                    <ListItem
                                                        key={"formation-option" + optionIndex} data-title={option.note}
                                                        sx={{
                                                            margin: 0,
                                                            padding: option.refoption === true ? 0 : 0.5
                                                        }}
                                                    >
                                                        <Grid container alignContent={'center'} alignItems={'center'}>
                                                            <Grid item xs={1}>
                                                                {option.ref && (
                                                                    <IconButton color="secondary"
                                                                        onMouseEnter={() => updateInfos(option)}  >
                                                                        <NoMaxWidthTooltip title={formattedInfos}  >
                                                                            <InfoIcon sx={{ fontSize: '14pt' }}></InfoIcon>
                                                                        </NoMaxWidthTooltip>
                                                                    </IconButton>
                                                                )}
                                                            </Grid>
                                                            <Grid item xs={10}
                                                            >
                                                                <Tooltip title={option.note} >
                                                                    <span>
                                                                        <Typography variant='body1'
                                                                            sx={{
                                                                                backgroundColor: option.principale
                                                                                    ? '#e5eef5'
                                                                                    : 'white',
                                                                                fontSize: '16px',
                                                                                padding: '5px',
                                                                                borderRadius: 3,
                                                                            }}
                                                                        > {option.name} {!option.refoption && `: ${option.value} pts`} </Typography>
                                                                    </span>
                                                                </Tooltip>
                                                            </Grid>
                                                            {option.max && (
                                                                <Grid item xs={1}>
                                                                    {option.nbrefoptions ? ( // Si `nbrefoptions` existe
                                                                        <IconButton
                                                                            onClick={() => {
                                                                                const relatedOptions = selectedFormationOptions.filter(opt => opt.refoption);

                                                                                if (option.nbrefoptions != null) {
                                                                                    openModal(option, relatedOptions);
                                                                                } else {
                                                                                    // Appeler directement `handleOptionSelect` si pas de `nbrefoptions`
                                                                                    handleOptionSelect(option, selectedCarteIndex, 1);
                                                                                }
                                                                            }}
                                                                        >
                                                                            <AddCircleIcon />
                                                                        </IconButton>
                                                                    ) : ( // Sinon, afficher un selecteur pour les options sans `nbrefoptions`
                                                                        <FormControl fullWidth>
                                                                            <Select
                                                                                variant="standard"
                                                                                size="small"
                                                                                value={option.selectedValue || 0} // La valeur sélectionnée par défaut
                                                                                onChange={(e) =>
                                                                                    handleOptionSelect(option, selectedCarteIndex, parseInt(e.target.value))
                                                                                }
                                                                            >
                                                                                {option.min !== 0 && <MenuItem value={0}>0</MenuItem>}
                                                                                {[...Array(option.max - option.min + 1)].map((_, i) => (
                                                                                    <MenuItem
                                                                                        key={`formation-option-item-${i + option.min}`}
                                                                                        value={i + option.min}
                                                                                    >
                                                                                        {i + option.min}
                                                                                    </MenuItem>
                                                                                ))}
                                                                            </Select>
                                                                        </FormControl>
                                                                    )}
                                                                </Grid>
                                                            )}
                                                            {!option.max && (
                                                                <Grid item xs={1} md={1} display="flex" justifyContent="flex-end">
                                                                    <IconButton
                                                                        onClick={() => {
                                                                            if (option.nbrefoptions != null) {
                                                                                const relatedOptions = selectedFormationOptions.filter(opt => opt.refoption);
                                                                                openModal(option, relatedOptions);
                                                                            }
                                                                            else {
                                                                                // Appeler directement `handleOptionSelect` si pas de `nbrefoptions`
                                                                                handleOptionSelect(option, selectedCarteIndex, 1);
                                                                            }
                                                                        }}
                                                                    >
                                                                        <AddCircleIcon />
                                                                    </IconButton>
                                                                </Grid>
                                                            )}
                                                        </Grid>

                                                    </ListItem>
                                                    <Divider variant='fullWidth' />
                                                </List>
                                            )
                                        )}
                                </Stack>
                            </CardContent>
                        </Card>
                    </Grid>
                    {/* Colonne carte */}
                    <Grid item xs={12} md={4}>
                        <Box sx={{ paddingBottom: 1 }}>
                            <Card sx={{ borderRadius: 5 }}>
                                <CardContent >
                                    <Grid container justifyContent={'left'} spacing={2}>
                                        <Grid item xs={3} md={3}>
                                            <Typography variant="h4">{t('list')}</Typography>
                                        </Grid>
                                        <Grid item xs={7} md={7}>
                                            < Tooltip title={t('open_all')}>
                                                <IconButton onClick={() => handleToggleAllAccordions(true)}>
                                                    <OpenInFullIcon >
                                                    </OpenInFullIcon>
                                                </IconButton>
                                            </Tooltip>
                                            < Tooltip title={t('close_all')}>
                                                <IconButton onClick={() => handleToggleAllAccordions(false)}>
                                                    <CloseFullscreenIcon >
                                                    </CloseFullscreenIcon>
                                                </IconButton>
                                            </Tooltip>
                                        </Grid>
                                        <Grid item xs={2} md={2} >
                                            {cartes.length > 0 && (
                                                <Box display="flex" justifyContent="flex-end">
                                                    <Tooltip title={t('tooltip.clear_list')}>
                                                        <span>
                                                            <IconButton className="remove-all-button" onClick={handleClickOpen} sx={{ displayPrint: 'none' }}><CleaningServicesIcon></CleaningServicesIcon></IconButton>
                                                            <Dialog open={open} onClose={handleClose}>
                                                                <DialogTitle id="alert-dialog-title">
                                                                    {t('dialog.clear_list_title')}
                                                                </DialogTitle>
                                                                <DialogContent>
                                                                    <DialogContentText id="alert-dialog-description">
                                                                        {t('dialog.clear_list_confirmation')}
                                                                    </DialogContentText>
                                                                </DialogContent>
                                                                <DialogActions>
                                                                    <Button onClick={handleClose}>{t('dialog.reject')}</Button>
                                                                    <Button onClick={handleRemoveAllCartes} autoFocus> {t('dialog.accept')}</Button>
                                                                </DialogActions>
                                                            </Dialog>
                                                        </span>
                                                    </Tooltip>
                                                </Box>
                                            )}
                                        </Grid>
                                        {alertRare && (
                                            <Alert severity='warning'
                                                variant="outlined">
                                                    {t('alert.rare_value_exceeded', { value: totalRareValue })}
                                                    </Alert>
                                        )}
                                    </Grid>
                                </CardContent>
                            </Card>
                        </Box>
                        <Stack spacing={1}>
                            {cartes.map((carte, carteIndex) => (
                                <Accordion disableGutters
                                    onChange={() => handleToggleAccordion(carteIndex)}
                                    expanded={accordionStates[carteIndex]}
                                    defaultExpanded={true}
                                    onClick={() => {
                                        handleCarteSelect(carteIndex);
                                        handleShowFormationOptions(carte.optionbase);
                                    }}// Sélectionner une carte en cliquant dessus
                                    sx={{ margin: "2px", border: selectedCarteIndex === carteIndex ? '2px solid #007bff' : '0px #ccc' }}

                                    key={carteIndex}
                                    className={`card ${selectedCarteIndex === carteIndex ? 'selected' : ''}`}
                                >
                                    <AccordionSummary expandIcon={<ExpandMoreIcon />} onChange={() => handleToggleAccordion(carteIndex)}>
                                        <Grid container direction="row" justifyContent="center" alignItems="center"                                        >
                                            <Grid item xs={2} md={2} sx={{ display: 'flex', justifyContent: 'flex-start' }} >
                                                <Tooltip title={t('tooltip.remove_formation')}>
                                                    <IconButton size='small'
                                                        onClick={() => handleRemoveCarte(carteIndex)} >
                                                        <CloseRoundedIcon>
                                                        </CloseRoundedIcon>
                                                    </IconButton>
                                                </Tooltip>
                                            </Grid>
                                            <Grid item xs={10} md={10} display={'flex'} alignItems={'center'} alignContent={'flex-start'}>
                                                <Typography variant='h6' component="span">
                                                    {carte.formation}
                                                    &nbsp;
                                                    {carte.GrpPrincipal && (
                                                        <Tooltip title={t('tooltip.main_formation')}>
                                                            <StarsIcon sx={{ fontSize: 15 }} />
                                                        </Tooltip>
                                                    )}
                                                    {accordionStates[carteIndex] === false && (
                                                        <span sx={{ fontSize: '10pt' }}>
                                                            {' '}
                                                            ({calculateCarteValue(carte)} {t('pts')})
                                                        </span>
                                                    )}
                                                </Typography>
                                            </Grid>
                                        </Grid>
                                    </AccordionSummary>
                                    <AccordionDetails sx={{ paddingTop: "1px" }}>
                                        <List >
                                            {carte.options.map((option, optionIndex) => (
                                                <ListItem key={optionIndex}
                                                    sx={{
                                                        margin: 0,
                                                        padding: 0,
                                                        paddingLeft: option.refoption ? 3 : 1,
                                                        backgroundColor: option.principale
                                                            ? '#ebf6fe'
                                                            : !option.refoption
                                                                ? '#f9fdff'
                                                                : 'white',
                                                        borderRadius: 3,
                                                    }}
                                                >
                                                    <Typography
                                                        style={{
                                                            fontWeight: option.principale === true ? 'bold' : option.tagrefoptions ? 'lighter' : 'normal',
                                                            fontSize: 14
                                                        }}
                                                    >


                                                        {((option.refoption || option.selectedValue > 1) && `${option.selectedValue} `)}
                                                        {option.name}
                                                        {option.valueSingle ? ` - ${option.value}` : (option.value > 0 && ` - ${option.value * option.selectedValue}`)}
                                                    </Typography>
                                                    <Tooltip title={t('tooltip.remove_option')}>
                                                        <IconButton onClick={() => handleOptionRemove(option, carteIndex)} sx={{ displayPrint: 'none' }} ><HighlightOffIcon color="warning" sx={{ fontSize: 15 }}></HighlightOffIcon></IconButton>
                                                    </Tooltip>
                                                </ListItem>
                                            ))}
                                        </List>
                                        <Typography variant='body1'>{t('total')} : {calculateCarteValue(carte)}</Typography>
                                    </AccordionDetails>
                                </Accordion>
                            ))}
                        </Stack>
                    </Grid>
                </Grid >
            )
            }

            {/* Modale des options spécifiques */}
            {
                modalOpen && (
                    <Modal open={modalOpen} onClose={() => setModalOpen(false)}>
                        <Box
                            sx={{
                                backgroundColor: 'white',
                                width: '50%',
                                maxHeight: '80vh',
                                position: 'absolute',
                                top: '50%',
                                left: '50%',
                                transform: 'translate(-50%, -50%)',
                                padding: 2,
                                borderRadius: 2,
                                boxShadow: 3,
                                overflowY: 'auto',
                            }}
                        >

                            {/* Titre */}
                            <Typography variant="h6">{modalMainOption.name}</Typography>

                            {/* Sélecteur principal */}
                            {modalMainOption.min !== undefined && modalMainOption.max !== undefined ? (
                                <Select
                                    value={modalMainOption.nbrefoptions} // Valeur synchronisée
                                    onChange={(e) => handleMainOptionChange(parseInt(e.target.value, 10))} // Gestion des modifications
                                    fullWidth
                                >
                                    {[...Array((modalMainOption.max || 1) - (modalMainOption.min || 0) + 1)].map((_, i) => (
                                        <MenuItem key={i} value={i + (modalMainOption.min || 0)}>
                                            {i + (modalMainOption.min || 0)}
                                        </MenuItem>
                                    ))}
                                </Select>
                            ) : (
                                remainingOptions > 0 && ( // Condition pour afficher le texte
                                    <Typography>
                                        {t('options.remaining', { count: remainingOptions })}
                                    </Typography>
                                )
                            )}

                            {/* Alertes conditionnelles */}
                            {remainingOptions === 0 && (
                                <Alert severity="success" style={{ marginTop: "8px" }}>
                                     {t('options.all_taken')}
                                </Alert>
                            )}
                            {remainingOptions < 0 && (
                                <Alert severity="error" style={{ marginTop: "8px" }}>
                                    {t('options.too_many')}
                                </Alert>
                            )}



                            <Grid container spacing={2}>
                                {modalOptions.map((opt) => (
                                    <Grid
                                        container
                                        item
                                        spacing={2}
                                        alignItems="center"
                                        key={opt.name}
                                    >
                                        {/* Nom de l'option */}
                                        <Grid item xs={8}>
                                            <Typography variant="subtitle1">{opt.name} {opt.value > 0 ? `: ${opt.value} pts` : ''}</Typography>
                                        </Grid>
                                        {/* Sélecteur pour l'option */}
                                        <Grid item xs={4}>
                                            <Select
                                                value={tempSelections[opt.name] ?? opt.min} // Valeur par défaut ou actuelle
                                                onChange={(e) => handleSelectionChange(opt.name, parseInt(e.target.value))}
                                            >
                                                {[...Array(opt.max - opt.min + 1)].map((_, i) => (
                                                    <MenuItem key={i} value={i + opt.min}>
                                                        {i + opt.min}
                                                    </MenuItem>
                                                ))}
                                            </Select>
                                        </Grid>
                                    </Grid>
                                ))}
                            </Grid>
                            <Grid container spacing={2} mt={3}>
                                <Grid item xs={6}>
                                    <Button
                                        variant="outlined"
                                        color="secondary"
                                        fullWidth
                                        onClick={() => setModalOpen(false)}
                                    >
                                        {t('cancel')}
                                    </Button>
                                </Grid>
                                <Grid item xs={6}>
                                    <Button
                                        variant="contained"
                                        color="secondary"
                                        fullWidth
                                        disabled={remainingOptions !== 0}
                                        onClick={validateModalSelections}
                                    >
                                        {t('validate')}
                                    </Button>
                                </Grid>
                            </Grid>
                        </Box>
                    </Modal>
                )
            }

            {/* Pop showOption */}
            <Popover
                open={openShow}
                anchorEl={anchorShow}
                onClose={handleCloseShow}
                anchorOrigin={{
                    vertical: 'bottom',
                    horizontal: 'left',
                }}
                transformOrigin={{
                    vertical: 'top',
                    horizontal: 'left',
                }}
            >
                {selectedShowOptions.map((option, optionIndex) => (
                    <List sx={{ margin: 0, padding: 0 }}>
                        <ListItem sx={{ margin: 0, padding: 0 }} key={"formation-option" + optionIndex} data-title={option.note}>
                            <Grid container alignContent={'center'} alignItems={'center'}>
                                <Grid item xs={12} padding={0.5}>
                                    <Typography variant='list'
                                        style={{
                                            paddingLeft: option.refoption ? 5 : 1,
                                            backgroundColor: option.principale
                                                ? '#ebf6fe'
                                                : !option.refoption
                                                    ? '#f9fdff'
                                                    : 'white',
                                            borderRadius: 3,
                                            fontSize: option.refoption ? '10px' : '12px',
                                            fontStyle: option.refoption ? 'italic' : 'normal',
                                            fontWeight: !option.refoption ? 'bold' : 'normal',

                                        }}
                                    >{option.name} : {option.value}  {t('pts')}
                                    </Typography>
                                </Grid>
                            </Grid>
                        </ListItem>
                    </List>
                ))}
            </Popover>
        </Container >
    )
}