import { Alert, Box, Card, CardContent, Container, Grid, List, ListItem, Typography, Paper } from '@mui/material';
import { useContext } from 'react';
import { MainContext } from '../Contexts/MainContext';

export default function PrintPage() {

    const {
        selectedCodexLogo,
        selectedCarteIndex,
        cartes,
        calculateCarteValue,
        selectedCodex,
        calculateTotalValue,
        maxCarte,
        displayPrintValue,
        alertRare,
        totalRareValue,
        selectedStrategie
    } = useContext(MainContext)

    return (
        <Container sx={{
            displayPrint: displayPrintValue,
            display: 'none', maxheight: '100vh', minHeight: '28cm', backgroundColor: 'grey', paddingBottom: 10
        }}
            maxWidth="100vw" >
            <Grid container marginTop={2} direction="row">
                <Grid item xs={12} sx={{ margin: 0, paddingBottom: 4 }}>
                    <Box >
                        <Card display="flex" sx={{ justifyContent: "center", alignContent: 'center', alignItems: 'center' }} >
                            <CardContent>
                                <Grid container >
                                    <Grid item xs={10} md={10}>
                                        <Typography variant="h4">Liste {selectedCodex} {calculateTotalValue()} pts</Typography>
                                    </Grid>
                                    <Grid item xs={2} md={2}><img src={process.env.PUBLIC_URL + '/' + selectedCodexLogo} /></Grid>
                                    <Grid item xs={4} md={4}><Typography variant='body2'>
                                        Strategie : <b>{selectedStrategie}</b>
                                    </Typography></Grid>
                                    <Grid item xs={4} md={4}><Typography variant='body2'>
                                        Nombre de formations : <b>{cartes.length}</b>
                                    </Typography></Grid>
                                    <Grid item xs={4} md={4}> <Typography variant='body2'>
                                        BLM : <b>{maxCarte.formation} {calculateCarteValue(maxCarte)} pts</b>
                                    </Typography>
                                    </Grid>
                                </Grid>
                            </CardContent>
                        </Card>
                    </Box>
                    {alertRare && (
                        <Alert severity='warning' variant="outlined">Attention, la valeur des formations rares ({totalRareValue}) dépasse les limites du codex</Alert>
                    )}
                </Grid>
            </Grid>
            <Grid container spacing={1} >
                {cartes.map((carte, carteIndex) => (
                    <Grid item xs={6} key={carteIndex}>
                        <Box >
                            <CardContent
                                sx={{ padding: 0, "&:last-child": { paddingBottom: 2 } }} // Pour enlever le paddingBottom par défaut
                                key={carteIndex}
                                className={`card ${selectedCarteIndex === carteIndex ? 'selected' : ''}`}
                            >
                                <Grid container sx={{ margin: 0, padding: 0, paddingBottom: 0 }}>
                                    <Grid item xs={10} md={10} >
                                        <Typography variant='h6'
                                            sx={{
                                                borderBottom: '1px solid grey', // Épaisseur et couleur du trait
                                                paddingBottom: '2px'             // Un peu de padding pour l'espace
                                            }}
                                        ><b>{carte.formation}</b> : {calculateCarteValue(carte)} pts </Typography>
                                    </Grid>
                                </Grid>
                                <List sx={{ margin: 0, padding: 0, paddingBottom: 0 }}>
                                    {carte.options.map((option, optionIndex) => (
                                        <ListItem key={option.id || optionIndex} sx={{ margin: 0, padding: 0, paddingBottom: 0 }}>
                                            <Typography variant='body2'
                                                sx={{ margin: 0, padding: 0, paddingBottom: 0 }}
                                            >
                                                {option.selectedValue > 1 && `${option.selectedValue} `}{option.name} - : {option.value * option.selectedValue}</Typography>
                                        </ListItem>
                                    ))}
                                </List>
                            </CardContent>
                        </Box>
                    </Grid>
                ))}
            </Grid>
        </Container >
    )
}
