import {
    AppBar, Box, Button, Dialog, DialogActions, DialogContent, DialogContentText,
    DialogTitle, Drawer, FormControlLabel, FormGroup, Grid, IconButton,
    List, ListItem, ListItemButton, ListItemIcon, ListItemText, SpeedDial,
    Switch, Toolbar, Typography, Divider,
    FormLabel
} from "@mui/material";
import PrintIcon from '@mui/icons-material/Print';
import { useContext, useRef } from "react";
import { MainContext } from "../Contexts/MainContext";
import SaveIcon from '@mui/icons-material/Save';
import FileUploadIcon from '@mui/icons-material/FileUpload';
import MenuIcon from '@mui/icons-material/Menu';
import ChevronLeftIcon from '@mui/icons-material/ChevronLeft';
import PublishedWithChangesIcon from '@mui/icons-material/PublishedWithChanges';
import RuleIcon from '@mui/icons-material/Rule';
import { useTranslation } from 'react-i18next';

export default function Header() {
    const inputRef = useRef();

    const {
        cartesSansNbacti,
        AlerteAutoClose,
        handlePrint,
        selectedCodexColor,
        selectedCodex,
        calculateTotalValue,
        maxCarte,
        calculateCarteValue,
        handleOpenCodexSelection,
        handleCloseChange,
        handleClickOpenChange,
        openChange,
        exportAllCartes,
        handlePrintCaracChange,
        handlePrintListChange,
        printCarac,
        printList,
        handleFileChange,
        handleToggleGameMode,
        selectedVersion,
        isGamePageVisible,
        CopyText, handleDrawerOpen, openDrawer, handleDrawerClose,
        handleRuleClick,
        isRulePageVisible
    } = useContext(MainContext);

    const handleFileUploadClick = () => {
        inputRef.current.click();
    };

    const { i18n, t } = useTranslation();

    const changeLanguage = (lng) => {
        i18n.changeLanguage(lng);
    };

    return (
        <>
            <AppBar
                position="fixed"
                sx={{
                    background: `${selectedCodexColor}`,
                    transition: 'background-color 1s ease',
                    displayPrint: 'none',
                }}
            >
                <SpeedDial
                    onClick={handleDrawerOpen}
                    ariaLabel={t('menu')}
                    sx={{ position: 'fixed', top: 1, right: 6 }}
                    icon={<MenuIcon />}
                />
                <Toolbar>
                    <Grid container direction="row" alignItems="center" spacing={1} marginRight={2}>
                        {!selectedCodex && (
                            <>
                                <Grid item xs={2} md={1.5}>
                                    <Box
                                        sx={{ height: '64px', alignItems: 'center', justifyContent: 'center' }}
                                        marginTop={1}
                                        marginLeft={-2}
                                    >
                                        <img
                                            src={process.env.PUBLIC_URL + '/logo10_weathering.png'}
                                            alt={t('logo_alt')}
                                            style={{
                                                maxHeight: '100%',
                                                objectFit: 'contain',
                                                position: 'center',
                                            }}
                                        />
                                    </Box>
                                </Grid>
                                <Grid item xs={10} md={10.5}>
                                    <Typography
                                        sx={{ display: { xs: 'none', sm: 'block' } }}
                                        variant="h4"
                                        align="left"
                                        color="#323232"
                                    >
                                        <b>{t('app.title.large')}</b>
                                    </Typography>
                                    <Typography
                                        sx={{ display: { xs: 'block', sm: 'none' } }}
                                        align="center"
                                        color="#323232"
                                        fontSize={26}
                                    >
                                        <b>{t('app.title.small')}</b>
                                    </Typography>
                                </Grid>
                            </>
                        )}
                        {selectedCodex && (
                            <>
                                <Grid item xs={8} md={3}>
                                    <Typography variant="subtitle1">
                                        <b>
                                            {t('selected_codex_version', {
                                                codex: selectedCodex,
                                                version: selectedVersion
                                            })}
                                        </b>
                                    </Typography>
                                </Grid>
                                <Grid item xs={6} md={1.5}>
                                    <Typography variant="subtitle1">
                                        {t('formations')}: {cartesSansNbacti.length}
                                    </Typography>
                                </Grid>
                                <Grid item xs={4} md={1}>
                                    <Typography variant="subtitle1">
                                        {t('points')}: <b>{calculateTotalValue()}</b>
                                    </Typography>
                                </Grid>
                                <Grid item xs={12} md={4}>
                                    <Typography variant="subtitle1">
                                        {t('blm')} : {maxCarte.formation} <b>{calculateCarteValue(maxCarte)}</b> {t('pts')}
                                    </Typography>
                                </Grid>
                            </>
                        )}
                    </Grid>
                </Toolbar>
                <AlerteAutoClose />
            </AppBar>

            <Drawer variant="persistent" anchor="right" open={openDrawer}>
                <Box sx={{ bgcolor: 'background.paper', displayPrint: 'none' }} alignContent="center" alignItems="center">
                    <List>
                        <ListItem disablePadding>
                            <IconButton onClick={handleDrawerClose}>
                                <ChevronLeftIcon fontSize="large" />
                            </IconButton>
                        </ListItem>
                    </List>
                    <Box>
                        <List>
                            {/* 1. Changer de codex */}
                            <ListItem disablePadding>
                                <ListItemButton onClick={handleClickOpenChange}>
                                    <ListItemIcon>
                                        <IconButton>
                                            <PublishedWithChangesIcon />
                                        </IconButton>
                                    </ListItemIcon>
                                    <ListItemText primary={t('change_codex')} />
                                </ListItemButton>
                                <Dialog open={openChange} onClose={handleCloseChange}>
                                    <DialogTitle color="black">{t('change_codex')}</DialogTitle>
                                    <DialogContent>
                                        <DialogContentText>
                                            {t('alert_change_codex')}
                                        </DialogContentText>
                                    </DialogContent>
                                    <DialogActions>
                                        <Button onClick={handleCloseChange}>{t('refuse')}</Button>
                                        <Button
                                            onClick={() => {
                                                handleOpenCodexSelection();
                                                handleDrawerClose();
                                            }}
                                            autoFocus
                                        >
                                            {t('accept')}
                                        </Button>
                                    </DialogActions>
                                </Dialog>
                            </ListItem>

                            {/* 2. Règles abrégées */}
                            <ListItem disablePadding>
                                <FormGroup>
                                    <ListItemButton>
                                        <FormControlLabel
                                            control={
                                                <Switch
                                                    onChange={() => {
                                                        handleRuleClick();
                                                        handleDrawerClose();
                                                    }}
                                                    checked={isRulePageVisible}
                                                    color="secondary"
                                                />
                                            }
                                            label={t('short_rules')}
                                        />
                                    </ListItemButton>
                                </FormGroup>
                            </ListItem>

                            <Divider />

                            {/* 3. Importer */}
                            <ListItem disablePadding>
                                <ListItemButton onClick={() => { handleFileUploadClick(); handleDrawerClose(); }}>
                                    <ListItemIcon>
                                        <IconButton>
                                            <FileUploadIcon />
                                        </IconButton>
                                    </ListItemIcon>
                                    <ListItemText primary={t('import')} />
                                    <input
                                        type="file"
                                        ref={inputRef}
                                        style={{ display: 'none' }}
                                        onChange={handleFileChange}
                                    />
                                </ListItemButton>
                            </ListItem>

                            {selectedCodex && (
                                <>
                                    {/* 4. Sauvegarder */}
                                    <ListItem disablePadding>
                                        <ListItemButton onClick={exportAllCartes}>
                                            <ListItemIcon>
                                                <IconButton onClick={exportAllCartes}>
                                                    <SaveIcon />
                                                </IconButton>
                                            </ListItemIcon>
                                            <ListItemText primary={t('save')} />
                                        </ListItemButton>
                                    </ListItem>

                                    {/* 5. Copier le texte (composant CopyText) */}
                                    <ListItem disablePadding>
                                        <CopyText />
                                    </ListItem>

                                    {/* 6. Game mode */}
                                    <ListItem disablePadding>
                                        <FormGroup>
                                            <ListItemButton>
                                                <FormControlLabel
                                                    control={
                                                        <Switch
                                                            onChange={() => {
                                                                handleToggleGameMode();
                                                                handleDrawerClose();
                                                            }}
                                                            checked={isGamePageVisible}
                                                            color="secondary"
                                                        />
                                                    }
                                                    label={t('game_mode')}
                                                />
                                            </ListItemButton>
                                        </FormGroup>
                                    </ListItem>
                                </>
                            )}
                        </List>
                    </Box>

                    {selectedCodex && !isGamePageVisible && (
                        <>
                            <Divider />
                            <List>
                                {/* 7. Imprimer */}
                                <ListItem disablePadding>
                                    <ListItemButton onClick={handlePrint}>
                                        <ListItemIcon>
                                            <IconButton onClick={handlePrint}>
                                                <PrintIcon />
                                            </IconButton>
                                        </ListItemIcon>
                                        <ListItemText primary={t('print')} />
                                    </ListItemButton>
                                </ListItem>

                                {/* 8. Options d'impression */}
                                <ListItem disablePadding>
                                    <FormGroup>
                                        <FormLabel component="legend">{t('print_options')}</FormLabel>
                                        <ListItemButton>
                                            <FormControlLabel
                                                control={
                                                    <Switch
                                                        defaultChecked={printList}
                                                        onChange={handlePrintListChange}
                                                    />
                                                }
                                                label={t('print_list')}
                                            />
                                        </ListItemButton>
                                        <ListItemButton>
                                            <FormControlLabel
                                                control={
                                                    <Switch
                                                        checked={printCarac}
                                                        onChange={handlePrintCaracChange}
                                                    />
                                                }
                                                label={t('print_characteristics')}
                                            />
                                        </ListItemButton>
                                    </FormGroup>
                                </ListItem>
                            </List>
                        </>
                    )}

                    {/* 9. Sélecteur de langue */}
                    <div style={{ margin: '1rem' }}>
                        <label htmlFor="lang-select">{t('select_language')}: </label>
                        <select
                            id="lang-select"
                            value={i18n.language}
                            onChange={(e) => changeLanguage(e.target.value)}
                        >
                            <option value="fr">🇫🇷 {t('french')}</option>
                            <option value="en">🇬🇧 {t('english')}</option>
                        </select>
                    </div>
                </Box>
            </Drawer>
        </>
    );
}
